1	/**
2	 * The screen a map builds itself on.
3	 *
4	 * The same canvas, the same panel and the same keyboard as every other map. What
5	 * is different is where the map comes from: it arrives claim by claim down one
6	 * request, with a reserved rectangle standing wherever the next one will go, and
7	 * every proposal the rules refused listed beside it.
8	 *
9	 * **There is no spinner here, and no moment where a blank screen turns into a
10	 * finished picture.** The growing *is* the loading state.
11	 *
12	 * **This screen does not ask for the map.** The press that opened it did
13	 * (`theRun.ts`), and this watches what that press started. It can be mounted,
14	 * unmounted and mounted again — which React's development mode does on purpose —
15	 * without a second generation being asked for, because there is no code here
16	 * that could ask for one.
17	 */
18	
19	import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react";
20	import { outlineOf } from "../a11y/sentences";
21	import { AddAClaim } from "../components/AddAClaim";
22	import { type Command, CommandPalette } from "../components/CommandPalette";
23	import { DoneLine } from "../components/DoneLine";
24	import { Inspector } from "../components/Inspector";
25	import { MapFrame } from "../components/MapFrame";
26	import { Outline } from "../components/Outline";
27	import { ReceiptStrip } from "../components/ReceiptStrip";
28	import { RefusalStrip } from "../components/RefusalStrip";
29	import { ReplayBadge, replaySentence } from "../components/ReplayBadge";
30	import { ShortcutsSheet } from "../components/ShortcutsSheet";
31	import { VerdictCard } from "../components/VerdictCard";
32	import { MapCanvas } from "../graph/Canvas";
33	import { useEveryKey } from "../keyboard/everyKey";
34	import type { MapKeys } from "../keyboard/useMapKeys";
35	import type { Selection } from "../world";
36	import { hasStopped } from "./growth";
37	import type { TheRun, WhereItHasGot } from "./theRun";
38	import type { Working } from "./transcript";
39	import { readTranscript } from "./transcript";
40	import "../components/generationDock.css";
41	
42	/**
43	 * Watch a run that is already going.
44	 *
45	 * `useSyncExternalStore` is React's own way of reading something that lives
46	 * outside React and changes on its own, and it is the right one here for a
47	 * reason that matters: subscribing and unsubscribing does nothing to the run.
48	 * A hook that *started* the generation would start two of them in development,
49	 * and *"never retry, a generation that ran twice would spend twice"* would be
50	 * broken on every machine where the app is developed.
51	 *
52	 * @param run The generation the press created.
53	 */
54	function useTheRun(run: TheRun): WhereItHasGot {
55	  return useSyncExternalStore(run.watch, run.now, run.now);
56	}
57	
58	/** What the screen needs. */
59	export interface GenerationScreenProps {
60	  /** The run, already asked for by the press that opened this screen. */
61	  readonly run: TheRun;
62	  /**
63	   * True when this copy has no model key, so the run is a recording being played
64	   * back. Known before the stream says anything, which is why the badge can be
65	   * on screen from the first frame — and why the offer to run it again can say
66	   * truthfully whether pressing it spends money.
67	   */
68	  readonly replaying: boolean;
69	  /** Ask for the same sentence again. A press, like the first one. */
70	  readonly onRunAgain: () => void;
71	  /** Let go of this run and go back. A press, and the only way off this screen. */
72	  readonly onLeave: () => void;
73	}
74	
75	/** A map building itself, and the panel beside it. */
76	export function GenerationScreen({ run, replaying, onRunAgain, onLeave }: GenerationScreenProps) {
77	  const { growth, saying } = useTheRun(run);
78	  const [selection, setSelection] = useState<Selection>(null);
79	  const [focused, setFocused] = useState<string | null>(null);
80	  const [overlay, setOverlay] = useState<"sheet" | "palette" | null>(null);
81	  const [dock, setDock] = useState<"panel" | "outline">("panel");
82	  const [openAt, setOpenAt] = useState<number | null>(null);
83	  const [status, setStatus] = useState(
84	    "Press ? for every key. j and k walk a column; h and l follow the wires.",
85	  );
86	  const [working, setWorking] = useState<Working>({ state: "reading" });
87	
88	  const { generationId, phase } = growth;
89	  const finished = hasStopped(phase);
90	
91	  // The same three keys as every other screen, from the one module that binds
92	  // them — this screen prints *Press ? for every key* under the map, and until
93	  // that module existed the press did nothing here.
94	  useEveryKey({
95	    everyKey: () => setOverlay((was) => (was === "sheet" ? null : "sheet")),
96	    palette: () => setOverlay((was) => (was === "palette" ? null : "palette")),
97	    escape: () => setOverlay(null),
98	  });
99	
100	  // The working of the run, read once the run has finished. It is asked for then
101	  // rather than as it goes, because the server writes it from the same pass that
102	  // writes the stream and a half-read one would be a second, staler copy.
103	  //
104	  // **A run that ended early has a working too**, and it is the one case where
105	  // reading it back matters most: it is the only record of how far the run got.
106	  useEffect(() => {
107	    if (generationId === null || !finished) {
108	      return;
109	    }
110	    let stillWanted = true;
111	    readTranscript(generationId).then(
112	      (read) => {
113	        if (stillWanted) {
114	          setWorking(read);
115	        }
116	      },
117	      // `readTranscript` answers rather than throws, for every failure it can
118	      // name. This is for the ones it cannot: a screen that waits for a promise
119	      // that will never settle says *Reading the working…* until the tab closes.
120	      () => {
121	        if (stillWanted) {
122	          setWorking({
123	            state: "gone",
124	            reason: "The working of this run could not be read, and nothing said why.",
125	          });
126	        }
127	      },
128	    );
129	    return () => {
130	      stillWanted = false;
131	    };
132	  }, [generationId, finished]);
133	
134	  const outline = useMemo(() => outlineOf(growth.world), [growth.world]);
135	
136	  // The keyboard follows the growing edge: a claim that has just arrived takes
137	  // focus, exactly as a claim a branch adds does. That is what keeps the newest
138	  // tile on the glass through a run that goes on for minutes — the canvas
139	  // already brings whatever the keyboard is on into view, so nothing here
140	  // re-frames the map and nothing re-lays it out. A tile that is already placed
141	  // stays exactly where it is; what moves is where the reader is looking.
142	  //
143	  // A claim that has just **arrived** takes focus, and nothing else does. The
144	  // count is what says one arrived: when the likelihoods land, the engine's own
145	  // world replaces the drawing and its claims come back in the map's order
146	  // rather than the order they were proposed in — which is not an arrival, and
147	  // moving the view for it would slide the map sideways at the very moment it
148	  // stopped changing.
149	  const howManyClaims = growth.world.claims.length;
150	  const seenSoFar = useRef(0);
151	  const lastArrived = useRef<string | null>(null);
152	  useEffect(() => {
153	    if (howManyClaims <= seenSoFar.current) {
154	      return;
155	    }
156	    seenSoFar.current = howManyClaims;
157	    const arrived = growth.world.claims[howManyClaims - 1]?.id ?? null;
158	    lastArrived.current = arrived;
159	    setFocused(arrived);
160	  }, [howManyClaims, growth.world.claims]);
161	
162	  // And it lets go the moment the run stops. Focus is also what the hover lens
163	  // reads, and a lens left on a claim the machine chose would dim the whole
164	  // finished map to fifteen per cent at exactly the moment the reader starts
165	  // reading it. If the reader has moved since, their focus is theirs and stays.
166	  useEffect(() => {
167	    if (!finished) {
168	      return;
169	    }
170	    setFocused((was) => (was === lastArrived.current ? null : was));
171	  }, [finished]);
172	
173	  const pick = useCallback((id: string) => {
174	    setFocused(id);
175	    setSelection({ kind: "claim", id });
176	  }, []);
177	
178	  // Nothing on this screen is bound to the map's own six operations yet, so the
179	  // keys that open them say so rather than doing nothing.
180	  /**
181	   * Every command this screen has, by name.
182	   *
183	   * **It is a screen's own list, not a copy of the stored map's.** A generated
184	   * map has no branches to open and none of the six things you can do to a
185	   * claim, so offering them here would be a palette full of commands that
186	   * explain why they cannot run. What it does have is the four ways around it
187	   * and the two things it can do, and each one is also a key or a control on
188	   * the screen — which is the palette's whole promise.
189	   *
190	   * Before this, ⌘K on this screen opened the shortcuts sheet: a key that
191	   * silently does something else is the one thing this product's keyboard is
192	   * not allowed to do.
193	   */
194	  const commands: Command[] = useMemo(
195	    () => [
196	      {
197	        name: "Read the map as a list",
198	        does: "The same as pressing O. Every claim, one sentence each, in the order they arrived.",
199	        run: () => {
200	          setDock("outline");
201	          setStatus("the map as a list");
202	        },
203	      },
204	      {
205	        name: "Read the panel beside the map",
206	        does: "The same as pressing O again. What this run refused, what it cost, and why.",
207	        run: () => {
208	          setDock("panel");
209	          setStatus("the panel beside the map");
210	        },
211	      },
212	      ...(generationId === null
213	        ? []
214	        : [
215	            {
216	              name: "Read the working of this run",
217	              does: "Every call it made, in order. The same as the control in the panel.",
218	              run: () => {
219	                setOpenAt(null);
220	                setDock("panel");
221	                setSelection({ kind: "generation", id: generationId });
222	              },
223	            },
224	          ]),
225	      {
226	        name: "Every key",
227	        does: "The sheet of every key on this map. The same as pressing ?.",
228	        run: () => setOverlay("sheet"),
229	      },
230	      {
231	        name: "Back to the launchpad",
232	        does: "Let this run go and start again. The same as the control at the top left.",
233	        run: onLeave,
234	      },
235	    ],
236	    [generationId, onLeave],
237	  );
238	
239	  const keys: MapKeys = useMemo(
240	    () => ({
241	      intervene: () => setStatus("a generated map takes edits through Add a claim, beside the map"),
242	      branch: () => setStatus("a branch is started on a stored map; this one is still being built"),
243	      flipWorlds: () => setStatus("there is nothing to flip to — no branch is open"),
244	      outline: () =>
245	        setDock((was) => {
246	          const next = was === "outline" ? "panel" : "outline";
247	          setStatus(next === "outline" ? "the map as a list" : "the panel beside the map");
248	          return next;
249	        }),
250	      panel: () => setStatus("the panel is beside the map"),
251	      palette: () => setOverlay("palette"),
252	    }),
253	    [],
254	  );
255	
256	  return (
257	    <MapFrame
258	      title={growth.world.title}
259	      onLeave={onLeave}
260	      onEveryKey={() => setOverlay("sheet")}
261	      where={
262	        <p className="map-bar__where">
263	          {/* Nothing sits over the map: the mark that says this run is a
264	              recording is a badge up here, and the sentence explaining it is in
265	              the line under the map with every other sentence about where this
266	              map came from. */}
267	          {replaying ? (
268	            <ReplayBadge
269	              recordingDate={growth.receipt?.recording_date ?? null}
270	              receiptMode={growth.receipt?.mode ?? null}
271	            />
272	          ) : null}
273	          {run.asked.target === null ? "Explore" : "Verify"}
274	          <span className="map-bar__side">
275	            {run.asked.target === null ? "what your sentence would cause" : run.asked.target}
276	          </span>
277	        </p>
278	      }
279	      map={
280	        <MapCanvas
281	          world={growth.world}
282	          selection={selection}
283	          onSelect={setSelection}
284	          focused={focused}
285	          onFocused={setFocused}
286	          mapKey={generationId ?? "a run that has not started"}
287	          keys={keys}
288	          onStatus={setStatus}
289	          onOverflow={() => setStatus("every claim is in the list beside the map")}
290	          arriving={!finished}
291	          reserved={growth.skeletons}
292	          // Framed once when the first rectangle is drawn, and once more when
293	          // the run stops — the one moment nothing on the map is moving and the
294	          // reader is about to start reading it.
295	          frameAgainOn={finished ? "the run stopped" : undefined}
296	        />
297	      }
298	      overlay={
299	        <>
300	          {overlay === "palette" ? (
301	            <CommandPalette open={true} onClose={() => setOverlay(null)} commands={commands} />
302	          ) : null}
303	          {overlay === "sheet" ? (
304	            <ShortcutsSheet open={true} onClose={() => setOverlay(null)} />
305	          ) : null}
306	        </>
307	      }
308	      status={status}
309	      // Said out loud, and said once — and it says what just **changed** rather
310	      // than re-reading the whole run. Here the same facts are already drawn:
311	      // the claims on the canvas, the refusals in the panel, why the run
312	      // stopped under the map. Printing them again made the foot of the screen
313	      // three strips of prose saying the same thing twice.
314	      saying={saying}
315	      spokenOnly={true}
316	      panel={
317	        /* The map as a list, in place of the panel, exactly as it is on a
318	           stored map: press O for it, press O again for the panel. It grows as
319	           the map grows, in the same causal order, so a reader who never sees
320	           the canvas hears the map being built rather than a silence followed
321	           by a finished list. */
322	        dock === "outline" ? (
323	          <Outline items={outline} onPick={pick} focused={focused} />
324	        ) : (
325	          <>
326	            {/* The Verify door's answer, at the top, when a destination was named. */}
327	            {growth.verdict === null || run.asked.target === null ? null : (
328	              <VerdictCard
329	                verdict={growth.verdict}
330	                target={run.asked.target}
331	                world={growth.world}
332	                onSelect={pick}
333	              />
334	            )}
335	
336	            <RefusalStrip
337	              refusals={growth.refusals}
338	              finished={finished}
339	              openAt={openAt}
340	              onOpen={(at) => {
341	                setOpenAt(at);
342	                setSelection({ kind: "generation", id: generationId ?? "" });
343	              }}
344	            />
345	
346	            {growth.receipt === null ? null : <ReceiptStrip receipt={growth.receipt} />}
347	
348	            {/* **One way into the working that is always there.**
349	                The panel's view of the run used to be reachable only from a
350	                refusal row or from the receipt strip's link — so a run that
351	                refused nothing had one way in, and only at the end, and a run
352	                whose stream was cut had none at all. That last one is the worst
353	                of the three: the working is the only record of how far a cut
354	                run got, the screen fetches it for exactly that reason, and then
355	                offered the reader no way to read it. */}
356	            {generationId === null ? null : (
357	              <section className="generation-working" aria-label="The working of this run">
358	                <button
359	                  className="generation-working__open"
360	                  type="button"
361	                  onClick={() => {
362	                    setOpenAt(null);
363	                    setDock("panel");
364	                    setSelection({ kind: "generation", id: generationId });
365	                  }}
366	                >
367	                  Read the working of this run <span aria-hidden="true">→</span>
368	                </button>
369	              </section>
370	            )}
371	
372	            {finished && growth.world.baseId !== "" ? (
373	              // The same control, the same words and the same refusals as the
374	              // one on a stored map's six-button panel. What differs is only
375	              // what happens next: a generated map has no branch panel on this
376	              // screen yet, so the claim is drafted, checked and said, and
377	              // putting it on a branch of this map is the next piece of work.
378	              // No branch is sent because there is none to send.
379	              //
380	              // **It waits for the map to have a name of its own**, which is the
381	              // engine's `base_id` arriving with the likelihoods. A run that
382	              // broke or whose stream was dropped never gets one, and offering
383	              // to add a claim to a map that has no identifier would send the
384	              // *run's* name to a route that asks for the map's.
385	              <AddAClaim
386	                baseId={growth.world.baseId}
387	                andThen="It is checked against this map and ready to go onto a branch of it."
388	              />
389	            ) : null}
390	
391	            <Inspector
392	              world={growth.world}
393	              selection={selection}
394	              generation={{
395	                seed: growth.seed,
396	                promptFingerprint: growth.receipt?.prompt_hash ?? null,
397	                working,
398	                unknown: growth.unknown,
399	                openAt,
400	              }}
401	            />
402	          </>
403	        )
404	      }
405	      origin={
406	        <>
407	          <p className="map-origin__line">{growth.world.origin}</p>
408	          {replaying ? (
409	            <p className="map-origin__line">
410	              {replaySentence({
411	                recordingDate: growth.receipt?.recording_date ?? null,
412	                receiptMode: growth.receipt?.mode ?? null,
413	              })}
414	            </p>
415	          ) : null}
416	          <DoneLine
417	            done={growth.done}
418	            failure={growth.failure}
419	            endedEarly={phase === "ended_early"}
420	            // The offer is made only where there is something to offer: a stream
421	            // that stopped without saying why. A run that finished has its map on
422	            // screen, and a button asking whether to spend it all again would be
423	            // a control looking for a reason to exist.
424	            runAgain={
425	              phase === "ended_early" ? { costsMoney: !replaying, go: onRunAgain } : undefined
426	            }
427	          />
428	          {(growth.world.warnings ?? []).map((warning) => (
429	            <p className="map-origin__line" key={warning}>
430	              {warning}
431	            </p>
432	          ))}
433	        </>
434	      }
435	    />
436	  );
437	}
438

