/*
 * The panel beside a map that is being generated.
 *
 * It holds more than the panel beside a stored map does — the Verify door's
 * answer, every refusal, what the run cost, the one edit that needs the model,
 * and the panel itself — so it is the one panel in this product that scrolls as
 * a whole rather than section by section.
 *
 * **Why as a whole.** A panel whose sections each scroll inside themselves hides
 * things twice over: a refusal can scroll out of the strip while the strip is
 * itself scrolled out of the panel, and a reader who looks away for a minute of
 * a run cannot tell what they have missed. Scrolling once means there is one
 * place to be, and everything that arrived is somewhere above or below it.
 */

.dock--generation {
  overflow-y: auto;
}

/* Inside a panel that scrolls as a whole, the section that reads out whatever is
 * selected is as tall as what is in it, like every other section. Left to its
 * own scrolling it would be a box inside a box, and the reader would have to
 * find which of the two was under the pointer. */
.dock--generation .inspector {
  flex: 0 0 auto;
  min-height: 0;
  overflow: visible;
}

/* ---- The foot of a generated map ----------------------------------------- *
 * What the run is doing is said in three channels, and each says it once: the
 * canvas draws it, the panel lists it, and the line under the map says why it
 * stopped. The live region is the fourth — the spoken one — and on this screen
 * it is spoken only. Printing it as well put the same sentence on the page
 * twice, in two of three stacked strips of prose at the foot of the screen.
 *
 * It is still a live region, still polite, and still read out in full. */
.map-live--spoken {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* One way into the working of this run, always there.
 *
 * It is a row of its own in the panel rather than a link inside the receipt
 * strip, because the receipt arrives at the end and a run whose stream was cut
 * never gets one — and the working is the only record of how far that run got.
 * Drawn like the strip's own link, because it opens the same thing. */
.generation-working {
  padding: var(--space-2) var(--space-3);
  background: var(--surface-raised);
}

.generation-working__open {
  padding: 0;
  border: none;
  background: none;
  font-family: inherit;
  font-size: var(--text-sm);
  color: var(--accent);
  cursor: pointer;
  text-align: left;
}

.generation-working__open:hover {
  text-decoration: underline;
