content.content:
1	/**
2	 * What a map being built says out loud.
3	 *
4	 * A reader who never sees the canvas should hear the map being built rather than
5	 * a silence followed by a finished list. So one polite line is said at each thing
6	 * that happened: the run starting, each claim arriving, each proposal the rules
7	 * turned down, the likelihoods landing, and why the run stopped.
8	 *
9	 * **Each line says what changed, and only what changed.** A live region that
10	 * re-reads the whole run on every arrival reads out every refusal again for the
11	 * tenth time on the tenth claim — so a reader listening to a ten-claim run with
12	 * two refusals hears those two sentences twenty times, and hears the thing that
13	 * just happened last, after a minute of things they already knew. The line a
14	 * screen reader speaks is therefore about the event: *a claim arrived*, *a
15	 * proposal was refused, with the rule's sentence*, *the likelihoods landed*,
16	 * *this is why it stopped* — each said once, at the moment it became true.
17	 *
18	 * **The ordering is the causality**, here as much as on the canvas. The lines are
19	 * said in the order the events arrived, which is the order the argument was
20	 * built, and the outline beside them grows in the same order.
21	 *
22	 * Nothing here composes a sentence about a refusal: a refused proposal is read
23	 * out in the words the rule itself wrote. And nothing here counts anything the
24	 * stream did not count — the claim and arrow counts at the end are the fields the
25	 * closing event carried.
26	 */
27	
28	import { THE_STREAM_ENDED_EARLY, WHY_IT_STOPPED } from "../components/DoneLine";
29	import type { Growth } from "../stream/growth";
30	import { inFewWords } from "../world/naming";
31	import { inWords } from "./sentences";
32	
33	/**
34	 * The first thing a reader hears: the request has gone, and a rectangle is held
35	 * open where the first claim will go.
36	 *
37	 * It is said once, when the screen appears, because it is the one statement that
38	 * is not about anything having changed.
39	 *
40	 * @param growth The run, as it stands before anything has come back.
41	 */
42	export function theOpeningLine(growth: Growth): string {
43	  return (
44	    `Asked for a map of "${growth.hypothesis}". A rectangle is held open where the first ` +
45	    `claim will go.`
46	  );
47	}
48	
49	/**
50	 * The one line to say now, given what just changed.
51	 *
52	 * @param was Everything known before the event.
53	 * @param now Everything known after it.
54	 * @returns The sentence, or the empty string when nothing a listener needs to
55	 *   hear changed — in which case the region keeps saying whatever it last said,
56	 *   rather than falling silent.
57	 */
58	export function whatChanged(was: Growth, now: Growth): string {
59	  // A refusal, in the rule's own sentences, said once and never said again.
60	  // Accepted and refused are two different events, so only one of the two
61	  // branches below can be the reason for any one change.
62	  if (now.refusals.length > was.refusals.length) {
63	    const last = now.refusals[now.refusals.length - 1];
64	    return last === undefined ? "" : `A proposal was refused. ${last.reasons.join(" ")}`;
65	  }
66	
67	  // The likelihoods landing: one event, one world, every number. It is the
68	  // engine's own world arriving that says so — a growing map has no count of
69	  // versions on it, because nothing has been run through it yet.
70	  if (was.world.versions === undefined && now.world.versions !== undefined) {
71	    return (
72	      "Every likelihood has been worked out, through the whole finished map, at once. Every " +
73	      "claim on the map now carries a number."
74	    );
75	  }
76	
77	  if (now.world.claims.length > was.world.claims.length) {
78	    const arrived = now.world.claims[now.world.claims.length - 1];
79	    return (
80	      `A claim arrived: "${inFewWords(arrived?.claim ?? "")}". ` +
81	      `${asClaims(now.world.claims.length)} so far, ` +
82	      `${asRectangles(now.skeletons.length)} still to come.`
83	    );
84	  }
85	
86	  if (now.verdict !== null && was.verdict === null) {
87	    // The engine's own sentence about where the reader said it ends, printed as
88	    // it came. Nothing here composes one.
89	    return now.verdict.why;
90	  }
91	
92	  if (now.phase !== was.phase) {
93	    return theEnd(now);
94	  }
95	
96	  return "";
97	}
98	
99	/** What a run that has stopped says, in one line, whichever way it stopped. */
100	function theEnd(now: Growth): string {
101	  switch (now.phase) {
102	    case "settled":
103	    case "stopped":
104	      return (
