57	const WAVE_SETTLES_AFTER = 1200;
58	
59	/**
60	 * What stands where a likelihood would go while the engine is being asked for
61	 * one.
62	 *
63	 * The shared vocabulary has three ways of saying a number is not there, and
64	 * this is the third of them — *nothing has been computed* — because that is
65	 * exactly what is true while a question is in flight: the engine has been asked
66	 * and has not answered, so nothing has worked this number through the map
67	 * **yet**. It is not a fourth kind of absence and it is not a spinner: the map
68	 * on screen keeps its shape, the slots that will move say why they are empty,
69	 * and the line under the map says what has been asked for and where.
70	 */
71	const WHILE_ASKING: Absence = absence(
72	  "no_engine",
73	  "The engine has been asked at /api/worlds for the map with this branch folded onto it, and " +
74	    "has not answered. Nothing has worked this number through the map yet.",
75	);
76	
77	/**
78	 * What stands where a likelihood would go when the engine **refused** the
79	 * branch.
80	 *
81	 * Not "no engine yet": the engine is there and it answered — it said the branch
82	 * does not fit the map, and it said why. The words have to be true of that, and
83	 * the vocabulary's first three rows are all about a number nobody has worked out
84	 * rather than one that could not be. So there is a **fourth row** — *the engine
85	 * refused the branch these numbers would come from* → **not worked out** — and a
86	 * kind of its own to go with it, because "nothing has run yet" invites waiting
87	 * and "the engine turned this down" invites repairing what it turned down.
88	 */
89	const REFUSED: Absence = absence(
90	  "refused",
91	  "The engine would not work this map out from this branch: the branch does not fit the map. " +
92	    "Every reason is beside the map, and nothing on the map has changed.",
